    33	                "compression",
    34	                EXR_ATTR_COMPRESSION,
    35	                0,
    36	                NULL,
    37	                &(curpart->compression));
    38	            if (rv != EXR_ERR_SUCCESS) return rv;
    39	            curpart->compression->uc = (uint8_t) EXR_COMPRESSION_ZIP;
    40	            curpart->comp_type       = EXR_COMPRESSION_ZIP;
    41	        }
    42	        else
    43	        {
    44	            return f->print_error (
    45	                f,
    46	                EXR_ERR_MISSING_REQ_ATTR,
    47	                "'compression' attribute not found");
    48	        }
    49	    }
    50	
    51	    if (!curpart->dataWindow)
    52	    {
    53	        if (adddefault)
    54	        {
    55	            exr_attr_box2i_t defdw = {{.x = 0, .y = 0}, {.x = 63, .y = 63}};
    56	            rv                     = exr_attr_list_add_static_name (
    57	                (exr_context_t) f,
    58	                &(curpart->attributes),
    59	                "dataWindow",
    60	                EXR_ATTR_BOX2I,
    61	                0,
    62	                NULL,
    63	                &(curpart->dataWindow));
